x;padding:24px}.dream-selector header{display:flex;justify-content:space-between;align-items:center;margin-bottom:23px;gap:12px}.dream-selector h2{font-size:23px;margin:0}.dream-selector small{color:#b2b2b2}.tag-group{display:flex;flex-wrap:wrap;gap:9px;margin-top:12px}.group-label{background:#caeaf2;font-weight:700;cursor:default}.record-actions{display:flex;gap:28px;margin-top:24px}.record-actions button{flex:1;padding:23px 12px;border:2px solid #7ea9b8;border-radius:12px;background:#f4fafc70;color:#3b7182;font:600 24px inherit;cursor:pointer;font-size:24px;font-weight:600}.record-actions button:last-child{background:#050505;border-color:white;color:white}.record-actions button:disabled{opacity:.5;cursor:wait}.notebook-message{color:#7c4d54}.dream-report{background:white;border:2px solid #d6c8d8;border-radius:25px;overflow:hidden;padding:0 30px 30px}.report-banner{display:flex;align-items:center;justify-content:space-between;background:#fff7e7;margin:0 -30px;padding:22px 30px;color:#dba461}.report-banner h2{font-size:26px;letter-spacing:.1em}.report-banner>span{font-size:42px}.report-note{font-size:12px;color:#879ca1}.dream-report article{margin:30px 0}.dream-report h3{font-size:22px;color:#437681;margin:0 0 18px}.dream-report article p{font-size:19px;line-height:1.95;color:#719aa5;margin:16px 0}.report-tags{display:flex;gap:8px;flex-wrap:wrap}.report-tags span{background:#e8f8f5;padding:3px 8px;color:#6f9f9f}.report-back{padding:13px 24px;border:1px solid #80a6b2;border-radius:12px;background:#edf7f8;color:#467786;font:inherit;cursor:pointer}button:focus-visible,textarea:focus-visible{outline:3px solid #748fcc;outline-offset:4px}@media(max-width:600px){.dream-notebook{padding:8px 10px 24px;border-radius:14px}.notebook-header{min-height:65px}.notebook-header h1{font-size:22px}.dream-paper{padding:22px}.dream-paper textarea{font-size:18px;min-height:330px}.paper-holes{margin-bottom:24px}.paper-holes i{width:11px;height:15px}.dream-selector{padding:18px 14px}.dream-selector h2{font-size:20px}.tag-group{gap:7px}.tag-group button,.group-label,.selected-tags button{font-size:14px;padding:9px 12px}.speak-dream{width:85%;font-size:22px}.speech-help{font-size:13px}.record-actions{gap:14px}.record-actions button{font-size:21px;padding:20px 8px}.dream-report{padding:0 20px 24px}.report-banner{margin:0 -20px;padding:18px}.report-banner h2{font-size:21px}.dream-report article p{font-size:17px}.dream-report h3{font-size:19px}}
.dream-notebook{box-sizing:border-box;width:100%;max-width:none;border:1px solid #e8e0ee;background:#faf7fc;--ink:#796b84}.notebook-header>button{color:#796b84}.notebook-header .archive-link{background:#ece4f3;color:#5f4c73;border:1px solid #dacee6}.dream-paper,.dream-selector{border:1px solid #e8e0ee;background:#fffdfF;box-sizing:border-box}.dream-paper textarea{color:#796b84}.word-count,.speech-help{color:#978aa1}.speak-dream{border-color:#dacee6;color:#796b84}.selected-tags button,.tag-group button.chosen{background:#ece4f3;border-color:#dacee6;color:#5f4c73}.group-label{background:#ece4f3;color:#796b84}.record-actions button{border-color:#dacee6;background:#ece4f3;color:#5f4c73}.record-actions button:last-child{background:#79658e;border-color:#79658e;color:#fff}
/* Keep the notebook typography consistent with the creative workshop. */
.dream-notebook{font-size:15px;line-height:1.7}.notebook-header h1,.dream-selector h2{font-size:22px;font-weight:500}.dream-paper textarea{font-size:16px;line-height:1.85;min-height:280px}.selected-tags button,.tag-group button,.group-label{font-size:15px;padding:7px 13px}.word-count{font-size:13px}.speak-dream{font-size:16px;padding:12px;border-width:1px}.speak-dream svg{width:19px;height:23px}.speech-help,.dream-selector small{font-size:12px}.record-actions{gap:16px}.record-actions button{font-family:inherit;font-size:16px;font-weight:500;padding:14px 12px;border-width:1px}.dream-report h3{font-size:20px}.dream-report article p{font-size:16px;line-height:1.85}.report-banner h2{font-size:22px}.notebook-header>button:first-child{font-size:30px}
@media(max-width:600px){.notebook-header h1,.dream-selector h2{font-size:20px}.dream-paper textarea{font-size:15px}.tag-group button,.group-label,.selected-tags button{font-size:14px}.speak-dream,.record-actions button{font-size:15px}.dream-report article p{font-size:15px}}
</style>
